record_badge:
function sigBadge(r){
  var e = (r.edition === 'signature') ? 'Signature edition' : 'Public edition';
  var v = r.verification_status || 'proposed';
  var l = r.ladder_rank || '';
  return '<div class="sigbanner"><span class="badge fact">' + e + '</span> <span class="badge">' + v + '</span> <span class="badge">' + l + '</span></div>';
}
